            function setCookie_persistentForApp(name, value, domain, path, sameSite, secure) {
                // 永続的な有効期限を設定（9999年12月31日）
                var expires = "; expires=Fri, 31 Dec 9999 23:59:59 GMT";
                var cookieString = name + "=" + value;
                cookieString += expires;

                if (domain) {
                    cookieString += "; domain=" + domain;
                }
                if (path) {
                    cookieString += "; path=" + path;
                }
                if (sameSite) {
                    cookieString += "; SameSite=" + sameSite;
                }
                if (secure) {
                    cookieString += "; Secure";
                }
                document.cookie = cookieString;
            }
            function getCookie_persistentForApp(name) {
                var cookies = document.cookie.split('; ');
                for (var i = 0; i < cookies.length; i++) {
                    var cookie = cookies[i].split('=');
                    if (cookie[0] === name) {
                        return cookie[1]; // 名前が一致した場合、その値を返す
                    }
                }
                return null; // 見つからない場合はnull
            }

            document.addEventListener('DOMContentLoaded', function() {
                window.addEventListener('wovnApiReady', function() {
                var selectedLanguage_cookie = getCookie_persistentForApp('selected_language') || 'ja';
                WOVN.io.changeLang(selectedLanguage_cookie);                                           //保持されたCookie値よりWOVNの言語を変更
                setCookie_persistentForApp("selected_language", selectedLanguage_cookie, ".pia.jp", "/", "None", true); //言語変更後にCookie設定
                });
            });

