                        $(this).html(data.html);
                        initCalendar();
                        initSideCal();
                        $(this).fadeIn("fast");
                    });
                }
            );
    }

    function initCalendar()
    {
        // Select a month.
        $("#cal-select select").on("change", function() {
            var param = $(this).val();
            showCalendar(param);
        });

        // Move previous or next month.
        $(".prev.arrow,.next.arrow").on("click", function(e) {
            e.preventDefault();
            var param = $(this).attr("href");
            showCalendar(param);
        });
    }

